"""Author Level 1 Week 2 as a connected lesson; keep source block positions."""
from pathlib import Path
import json,copy
R=Path(__file__).resolve().parents[1];p=R/'content/programme.json';d=json.loads(p.read_text());w=next(x for x in d['weeks'] if x['id']=='ai-1/2')
if w['sections'][0].get('reading_flow'):raise SystemExit('Week 2 already authored; edit its metadata directly.')
original=copy.deepcopy(w)
def add(role,n,text=None,image=None,label=None):
 b=copy.deepcopy(image) if image else {'type':'paragraph','text':text,'presentation':{'kind':'body','paragraphs':[text],'emphasis':[]}}
 if label:b.setdefault('presentation',{})['label']=label
 b['reading_addition']='week2-connected-reading';w[role][n-1]['blocks'].append(b);return len(w[role][n-1]['blocks'])-1
def pic(n):return next(b for b in w['sections'][17]['blocks'] if b.get('src','').endswith(f'academy-story-ai-1-2-{n:02}'))
def g(title,indices,kind='text',collapsed=False,note=None):return {'title':title,'kind':kind,'indices':indices,**({'collapsed':True} if collapsed else {}),**({'note':note} if note else {})}
def design(role,n,title,purpose,groups,optional=False):
 s=w[role][n-1];used=[i for z in groups for i in z['indices']];assert len(used)==len(set(used)),(role,n)
 rest=[i for i in range(len(s['blocks'])) if i not in used]
 if rest:groups.append(g('Earlier wording, alternative practice and picture transcripts',rest,'reference',True))
 s['reading_flow']={'title':title,'purpose':purpose,'optional':optional,'groups':groups};s['reading_intro']=purpose
 assert sorted(i for z in groups for i in z['indices'])==list(range(len(s['blocks'])))

start=add('sections',1,'A screen shows three book titles. Has the computer spoken, reserved a book, or read a whole story? This week, follow the information one step at a time before crediting a system with extra actions.')
design('sections',1,'What happened to the information?','Trace what enters, what changes and what comes out. Then ask which details were kept.',[g('Start with a puzzle',[start],'example'),g('Reconnect with Week 1',[13,5,7]),g('By the end, you can…',[1,2,3],'prompts')])
design('sections',2,'A title on a screen is not a spoken book','Read the supplied facts before deciding what the kiosk has done.',[g('Meet Sam at the library kiosk',[13],'example'),g('Follow the information',[14]),g('Connect the mechanism to Week 1',[15]),g('Explain the difference',[6,9],'prompts')])
path=add('sections',3,'Read each row as its own possible stage. The first row is the supplied kiosk. The speech and borrowing rows describe extra stages that would need to exist and run; they are not evidence that this kiosk performed them.')
design('sections',3,'One stage’s output can become another stage’s input','Name the actual content at each arrow, not just the word “text”.',[g('Read the three possible stages',[path,13]),g('A title is smaller than a whole book',[14],'example'),g('A suggestion is different from a loan',[15]),g('Connect to another system',[10,17])])
# Match each comparison picture with its own caption.
gallery={'type':'gallery','layout':'reading-cards','reading_addition':'week2-connected-reading','cells':[[copy.deepcopy(w['sections'][3]['blocks'][3+i]),copy.deepcopy(w['sections'][3]['blocks'][7+i])] for i in range(4)]}
w['sections'][3]['blocks'].append(gallery);idx=len(w['sections'][3]['blocks'])-1
design('sections',4,'Compare the roles, not just the pictures','Input and output depend on which stage you are describing.',[g('Four clues, paired with their explanations',[idx],'cards'),g('Discuss the confusing pair',[12],'prompts'),g('Keep a limit in view',[11],'example')])
design('sections',5,'Your quick word guide','Use these words when they help you explain a particular arrow or missing detail.',[g('Input, process, output and trace',[7]),g('Representation and information loss',[13]),g('Repair a claim using a word',[9,10],'prompts')],True)
comparison=add('sections',6,image=pic(3));steps=add('sections',6,image=pic(2));change=add('sections',6,image=pic(4))
predict=add('sections',6,'Before opening the changed-case picture: suppose the device stores total AND red count. What would each box’s record be? Could you now find its blue count? Try it using the two-colour assumption.')
design('sections',6,'Two different boxes. The same stored total.','A correct total can still leave out the detail needed for your next question.',[g('The case and its given facts',[18,20,21],'example'),g('Compare the original boxes',[comparison]),g('Follow what the device keeps',[steps]),g('Why the colour counts cannot be recovered',[26]),g('Predict a richer record',[predict],'prompts'),g('Check the changed record',[change],'example',True),g('Respect the assumption',[28],'example'),g('Use the richer record',[29],'prompts')])
design('sections',7,'Find the first wrong stage','A correct calculation can still use an incorrectly recorded input.',[g('Investigate a wrong catalogue result',[11],'example'),g('Check intermediate values',[12]),g('Repair two tempting claims',[5,7,9,13],'prompts')])
visitor=add('sections',8,'Your W2 case: only total visitors=3 was kept. Write two possible arrival schedules with that same total. Use their different busiest-hour patterns to explain what the total cannot tell you.')
design('sections',8,'Practise: what can one number tell us?','Construct two possible originals that share a summary but answer a question differently.',[g('Model the method with temperatures',[11,12],'example'),g('Now try the visitor record',[visitor,15,16,13],'steps'),g('Explain, check and switch roles',[17]),g('Challenge “every output is the final action”',[19,20],'prompts'),g('Check the pencil explanation',[22,23,24])])
lab=add('sections',9,'Use this fictional paper music helper. Input: one mood word. Rule: “calm” returns Quiet River; “lively” returns Jumping Feet; a missing or unrecognised mood returns “Please choose calm or lively.” Its output is a displayed title or request, not audio. These are toy titles, and this rule is not a trained model.')
labsteps=add('sections',9,'In pairs, predict the result for calm. Then let your partner apply the written rule and record the paper-trace result. Swap roles and try a missing mood. Keep the predicted result separate from what your partner actually produced; a paper trace is not a run of an AI model.')
design('sections',9,'Investigate a runnable music helper','Use a supplied rule so your prediction, trace and explanation can be checked.',[g('Your fictional system',[lab],'example'),g('Predict, trace and swap',[labsteps,6,7,8],'steps'),g('Record normal and missing-input cases',[9,12])])
design('sections',10,'Choose a harder thinking challenge','Choose one next step; you do not need to complete the entire ladder.',[g('Pick a useful challenge',list(range(4,11)),'prompts')],True)
design('sections',11,'Build your sorter’s information map','Keep the information your decision needs and name the details you leave out.',[g('This week’s design decision',[4,14],'example'),g('Plan the stages and review point',[5,6,7,8,9],'prompts'),g('Avoid a larger claim',[11])])
design('sections',12,'Reference: check any information-path explanation','Use after practice. The four-score case is this week’s selected independent attempt.',[g('Check your trace and its limits',[5,6,7,8,9],'prompts'),g('Record the support you used',[12])],True)
design('sections',13,'Extra practice: mood in, titles out','Try the playlist question before opening its worked explanation.',[g('Read the case and question',[3,5],'example'),g('Try your explanation',[9,10],'prompts'),g('Check after trying',[7,13],'example',True)],True)
design('sections',14,'Try alone: does a total reveal every score?','Keep one first attempt before hints or teacher feedback.',[g('The new case',[1,2],'example'),g('Keep the attempt fair',[3,17]),g('Use feedback after your first attempt',[22])])
design('sections',15,'Reference: the original lesson checklist','Use this if you want an additional checklist of this week’s learning targets.',[g('Targets and evidence',[1]),g('Keep your original prediction',[2,3])],True)
design('sections',16,'Finish: trace, explain and name a loss','Close your notes and give an explanation you can defend.',[g('Your exit explanation',[0,1],'prompts'),g('Choose support and plan a return',[2,3])])
for role,n in [('sections',17),('workbook',20)]:
 design(role,n,'Extra practice: pictures, repair and feedback','Attempt each question before opening its explanation. Use one paper or browser copy.',[g('First supported question',list(range(1,10)),'prompts'),g('Check the first explanation',[10],'example',True),g('Changed-record question',list(range(11,18)),'prompts'),g('Check the changed record',[18],'example',True),g('Repair and save your work',[20,22]+([23] if role=='workbook' else []))],True)
design('sections',18,'Reference: the six-picture journey','Revisit the diagram that serves your current question; the main pictures already sit beside their explanations.',[g(w['sections'][17]['blocks'][4*i]['text'],list(range(4*i+1,4*i+4))) for i in range(6)],True)

# Teacher edition: teach the same connected path; keep solutions in this edition.
design('teacher',1,'Prepare the information-path lesson','Plan one route through tracing, information loss, diagnosis and independent explanation.',[g('Learning goals and preparation',[1,19,26]),g('What to prepare',[16,22,23,24],'prompts'),g('Main teaching plan',[2,3]),g('Retrieve Week 1',[6,7,8,21],'example')])
tp=add('teacher',2,image=pic(3));ts=add('teacher',2,image=pic(2))
design('teacher',2,'Teach the path and the information it loses','Keep the kiosk, book records and pencil boxes attached to the same question: what does this record support?',[g('Begin with Sam’s kiosk',[20,21,22],'example'),g('Separate titles, speech and borrowing',[23,24]),g('Choose a representation for a question',[29,30,31],'example'),g('Use the pencil-box counterexample',[35,37,38,tp,ts,43],'example'),g('Store one more field',[47,48,49],'steps'),g('Keep the two-colour assumption',[45]),g('Use the picture deliberately',[33,51])])
design('teacher',3,'Guide practice, then remove the help','Use visitor schedules to check whether learners can construct a counterexample themselves.',[g('Prompt before revealing',[16],'example'),g('Listen for two valid schedules',[17,18]),g('Check the multi-stage misconception',[20,21,22],'example'),g('Return to the pencil question',[24,26,27,28]),g('Keep each learner explaining',[7,8,10],'prompts')])
tl=add('teacher',4,'Use the student lesson’s fictional two-mood helper: calm → Quiet River; lively → Jumping Feet; missing or unrecognised mood → ask for calm or lively. Pairs predict, then apply the rule on paper. A calm input produces the first title; a blank input produces the request. Distinguish a paper trace from a real software run. Reserve the four-score case for the individual first attempt.')
design('teacher',4,'Run the music-helper investigation','A fully specified rule makes the expected and actual paper trace inspectable.',[g('Prepare the supplied toy system',[tl],'example'),g('Run and record the cases',[3,4,5,6],'steps'),g('Keep a checkable record',[10]),g('Diagnose the first misunderstanding',[15,16,17],'cards'),g('Choose the next teaching action',[19,20])])
design('teacher',5,'Assess the four-score explanation','Reserve this answer until the learner has made the first independent attempt.',[g('Selected independent question and key',[31,33],'example'),g('Judge explanation, trace and limits',[34,35]),g('Give feedback that changes the next attempt',[37]),g('Workbook W1: catalogue filter',[16,17],'example'),g('Workbook W2: visitor schedules',[19,20],'example'),g('Workbook W3: sufficient information',[22,23],'example'),g('Workbook W5: voice-calculator diagnosis',[28,29],'example')])
design('teacher',6,'Connect, adapt and revisit','Retain one project map and use changed cases to check understanding later.',[g('Project evidence to keep',[2,3,20]),g('Support without giving away the reasoning',[5,11,12]),g('Plan and record the return check',[15,16,17,18]),g('Bridge to sensors',[7,9,13])])
design('teacher',7,'Reference: alternative planning checklist','Use this as a planning reminder alongside the main route, rather than repeating a second lesson.',[g('Preparation and schedule',[0,1,2]),g('Practice and assessment reminders',list(range(3,13)))],True)
design('teacher',8,'Reference: feedback and digital records','The paper activities need no coding account; use tools when they help retain evidence.',[g('Separate practice and assessment',[0,1]),g('Repair and portfolio record',[3,4])],True)
design('teacher',9,'Reference: teach with the six pictures','Choose the image for the teaching move, then use its adjacent explanation.',[g(w['teacher'][8]['blocks'][1+5*i]['text'],list(range(2+5*i,6+5*i))) for i in range(6)],True)

# Workbook: one main answer record per task; repeated copies are references.
main=[(1,'Recall · Follow last week’s decision','Retrieve before checking your notes.',[g('Your first explanation',[0,2,3],'prompts')]),(12,'W1 · Trace the library request','Check both conditions and identify the surviving record.',[g('Read, trace and explain',[0,1],'prompts')]),(13,'W2 · Two schedules, one total','Show why the summary cannot determine the busiest hour.',[g('Try the visitor case',[0,1],'prompts')]),(14,'W3 · Choose enough information','Match each question to the information needed to answer it.',[g('Explain each choice',[0,1],'prompts')]),(16,'W5 · Find the first incorrect stage','Trace the spoken request, transcript and arithmetic before choosing a repair.',[g('Diagnose the voice calculator',[0,1],'prompts')]),(4,'W4 · Explain a new information loss','Keep one first attempt on the four-score case before feedback.',[g('Read and explain independently',[1,2],'example'),g('Record any support',[3])]),(9,'Project · Draw your sorter’s information path','Label the input, transformation, output and human review point.',[g('Your map and evidence',[0,1,2],'prompts')]),(17,'Feedback · Repair, then return','Keep the first attempt, the reason for a repair and a later changed-case check.',[g('Your evidence record',[0,1])]),(10,'Finish · Check what your work shows','Point to a trace, an explanation and a limit before choosing a confidence level.',[g('Your self-check',[0,1])])]
for n,title,purpose,groups in main:design('workbook',n,title,purpose,groups)
refs={2:('Reference · Visitor practice record','This is the same W2 attempt. Use one response record.'),3:('Extra practice · Is every output final?','Use a multi-stage example to repair the claim.'),5:('Reference · The kiosk target','Return to the target when checking your explanation.'),6:('Extra practice · Playlist helper','Try before checking the student worked explanation.'),7:('Extra practice · Fan and missing reading','This is additional practice; keep the four-score first attempt separate.'),8:('Extra practice · Design a useful test','Write a prediction before tracing or testing.'),11:('Reference · Kiosk response space','The kiosk was used in teaching. This response is practice.'),15:('Reference · Four-score response copy','This duplicates W4. Reuse its first-attempt record.'),18:('Extra practice · The pencil record','Use the worked picture and record what support you needed.'),19:('Reference · Sorter portfolio record','Extend your main project record if needed.'),21:('Reference · Six-picture response sheets','Choose the relevant picture rather than completing all six again.')}
for n,(title,purpose) in refs.items():
 s=w['workbook'][n-1]
 groups=([g(s['blocks'][5*i]['text'],list(range(5*i+1,5*i+5))) for i in range(6)] if n==21 else [g('Use this when helpful',list(range(len(s['blocks']))))])
 design('workbook',n,title,purpose,groups,True)

overviews={
 'sections':('Follow the information. Notice what is lost.','Start with a library kiosk, trace the pencil-box summary, practise with visitor records, then explain a new case.','Name the exact input → trace the transformation → state what the output cannot tell you.',[1,2,3,4,6,7,8,9,14,11,16,5,10,12,13,15,17,18],[('Notice',2),('Trace',3),('Compare records',6),('Practise',8),('Try alone',14),('Build & reflect',11)]),
 'teacher':('Teach one information story.','Trace the kiosk, model information loss, guide visitor schedules, run the supplied music rule and reserve the four-score case for independent evidence.','Look for a valid trace, two originals when needed, and a defensible limit.',list(range(1,10)),[('Prepare',1),('Explain',2),('Guide',3),('Investigate',4),('Assess',5),('Return',6)]),
 'workbook':('One connected information record.','Trace a request, compare summaries, choose needed information, diagnose an error and attempt the reserved new case.','Keep a first attempt, its supporting trace and a correction you can explain.',[1,12,13,14,16,4,9,17,10,2,3,5,6,7,8,11,15,18,19,20,21],[('Recall',1),('Trace',12),('Compare',13),('Choose',14),('Diagnose',16),('Try alone',4)])}
for role,(title,lead,outcome,order,route) in overviews.items():
 w[role][0]['reading_flow']['overview']={'title':title,'lead':lead,'outcome':outcome,'order':order,'route':[{'label':label,'section':n} for label,n in route]}
 for before,after in zip(original[role],w[role]):assert before['blocks']==after['blocks'][:len(before['blocks'])]
p.write_text(json.dumps(d,ensure_ascii=False,indent=2))
(R/'reports/week2-connected-reading.json').write_text(json.dumps({'lesson':w['id'],'sections_reviewed':48,'original_blocks_preserved':True,'roles':{role:{'main_sections':sum(not s['reading_flow']['optional'] for s in w[role]),'reference_sections':sum(s['reading_flow']['optional'] for s in w[role]),'sections':[{'title':s['reading_flow']['title'],'groups':[g['title'] for g in s['reading_flow']['groups']]} for s in w[role]]} for role in overviews}},indent=2)+'\n')
print('Authored all 48 Week 2 sections; source blocks retained.')
